pub struct Format;

impl Format {
    pub fn percentage(value: f32) -> String {
        Self::percentage_with_precision(value, 1)
    }

    pub fn percentage_with_precision(value: f32, precision: usize) -> String {
        format!("{:.*}%", precision, f64::from(value * 100.0_f32))
    }

    pub fn progress(current: usize, total: usize) -> String {
        Self::percentage(Self::ratio(current, total))
    }

    pub fn bar(current: usize, total: usize, width: usize) -> String {
        let ratio = Self::ratio(current, total).clamp(0.0, 1.0);
        let filled = ((ratio * width as f32).floor()) as usize;

        let body = if width == 0 {
            String::new()
        } else if filled >= width {
            "=".repeat(width)
        } else {
            format!("{}>{}", "=".repeat(filled), " ".repeat(width - filled - 1))
        };

        format!("[{}] {}", body, Self::percentage(ratio))
    }

    fn ratio(current: usize, total: usize) -> f32 {
        if total == 0 {
            0.0
        } else {
            current as f32 / total as f32
        }
    }
}

